import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Euler,
  Vector3,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ load: (url: string) => import('three').Texture }} textureLoader
 * @property {{ [key: string]: (obj: Object3D, params: any) => void }} primitives
 * @property {{ fontAtlas: any }} fontAtlas
 */

/**
 * Creates the Features card 3 node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  const { assets = {}, position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1] } = config;

  // Load the brushed-metal texture
  const tex = ctx.textureLoader.load(assets.imageUrl);

  // Plane geometry (unit size, will be scaled via object scale)
  const geometry = new PlaneGeometry(1, 1);

  // Basic node material using the texture as color
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(tex);
  material.transparent = true;

  // Mesh
  const mesh = new Mesh(geometry, material);

  // Apply transforms
  mesh.position.set(...position);
  mesh.rotation.set(...rotation);
  mesh.scale.set(...scale);

  // User data for event handlers and cleanup
  mesh.userData = {
    handlers: {},
    cleanup: () => {
      // Stop any gsap timelines (none expected here but safe)
      gsap.killTweensOf(mesh);
      geometry.dispose();
      material.dispose();
      // Dispose texture only if it is not shared (optional guard)
      if (tex && tex.dispose) tex.dispose();
    },
  };

  // No cinematic primitives to apply for this node
  // (If any were listed, they would be applied here via ctx.primitives)

  return mesh;
}
